// Access flow memory for slot session tracking
let slotTickets = flow.get("slotTickets") || {};
let previousSlots = flow.get("previousSlots") || { slot1: "Free", slot2: "Free", slot3: "Free", slot4: "Free" };

let currentSlots = {
    slot1: msg.payload.slot1,
    slot2: msg.payload.slot2,
    slot3: msg.payload.slot3,
    slot4: msg.payload.slot4
};

let chatId = 6749735109;
const RATE_PER_SECOND = 1;

let messageToSend = null;

// CHECK ALL 4 SLOTS FOR ENTRY OR EXIT
for (let s = 1; s <= 4; s++) {
    let slotKey = "slot" + s;

    // In case of an Entry Detection, Slot changed from Free to Occupied
    if (previousSlots[slotKey] === "Free" && currentSlots[slotKey] === "Occupied") {
        let ticketId = "TICK-" + Math.floor(1000 + Math.random() * 9000);
        let entryTime = Date.now();

        // Store ticket against the SPECIFIC slot number
        slotTickets[slotKey] = { ticketId: ticketId, entryTime: entryTime };

        let text = `🚗 *WELCOME TO PARKING*\n` +
            `----------------------------\n` +
            `🎟️ *Ticket ID:* \`${ticketId}\` (Slot ${s})\n` +
            `⏱️ *Entry Time:* ${new Date(entryTime).toLocaleTimeString()}\n` +
            `💰 *Rate:* 1 EGP / second\n\n` +
            `*Gate Opening... Please park safely!*`;

        messageToSend = { payload: { chatId: chatId, type: 'message', content: text, options: { parse_mode: 'Markdown' } } };
    }

    // In case of an Exit Detection, Slot changed from Occupied to Free
    if (previousSlots[slotKey] === "Occupied" && currentSlots[slotKey] === "Free") {
        let session = slotTickets[slotKey];

        if (session) {
            let exitTime = Date.now();
            let durationSeconds = Math.max(1, Math.round((exitTime - session.entryTime) / 1000));
            let totalCost = durationSeconds * RATE_PER_SECOND;

            let receipt = `🧾 *PARKING RECEIPT*\n` +
                `----------------------------\n` +
                `🎟️ *Ticket ID:* \`${session.ticketId}\` (Slot ${s})\n` +
                `⏱️ *Duration:* ${durationSeconds} second(s)\n` +
                `💵 *Rate:* 1 EGP / second\n` +
                `----------------------------\n` +
                `💳 *TOTAL DUE:* *${totalCost} EGP*\n\n` +
                `Thank you for parking with us! Have a safe drive! 🚗`;

            // Clear this slot's session
            delete slotTickets[slotKey];

            messageToSend = { payload: { chatId: chatId, type: 'message', content: receipt, options: { parse_mode: 'Markdown' } } };
        }
    }
}

// Update state memory
flow.set("slotTickets", slotTickets);
flow.set("previousSlots", currentSlots);

return messageToSend;
